class Solution {
public:
    int maxScore(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int ans = INT_MIN;
        for (int i = 0; i < m; ++i) {
            int ending = grid[i][0];
            for (int j = 1; j < n; ++j) {
                int twoOrMore = ending + grid[i][j];
                ans = max(ans, twoOrMore);
                ending = max(grid[i][j], twoOrMore);
            }
        }
        for (int j = 0; j < n; ++j) {
            int ending = grid[0][j];
            for (int i = 1; i < m; ++i) {
                int twoOrMore = ending + grid[i][j];
                ans = max(ans, twoOrMore);
                ending = max(grid[i][j], twoOrMore);
            }
        }
        for (int i = 1; i + 1 < m; ++i)
            for (int j = 1; j + 1 < n; ++j)
                ans = max(ans, grid[i][j]);
        return ans;
    }
};
